/**
 * Battery — programmatic access to a locally logged-in Claude Code account.
 *
 * This is the original `claude-code-battery` package, folded into extend-kit.
 * It reads the credentials Claude Code stores on this machine (keychain on
 * macOS, a credentials file elsewhere) and calls Claude's account API with
 * them, which is why it cannot be bundled into the plugin: it needs the
 * user's own machine and their own login.
 */
export { CcbError } from './errors.js';
export { getCredentials, getAccessToken, isTokenExpired, isApiKeyAuth } from './auth/index.js';
export type { ClaudeCredentials, ClaudeOAuthCredentials, ApiKeyAuth, ClientAuth } from './auth/index.js';
export { ClaudeCodeClient, OAuthApi } from './api/index.js';
export type { UsageResponse, UsageBucket, ExtraUsage, ProfileResponse, AccountInfo, OrganizationInfo, ApplicationInfo, } from './api/index.js';
